// Ko'p tillilik: o'zbek (lotin/kirill), rus, ingliz.
// Kalit — o'zbekcha lotin matn. Kirill avtomatik transliteratsiya qilinadi.
import { toCyrillic } from './translit.js';

export const LANG_NAMES = { uz: "O'zbekcha", uzc: 'Ўзбекча', ru: 'Русский', en: 'English' };

function detect() {
  try {
    const s = localStorage.getItem('sh_lang');
    if (s && LANG_NAMES[s]) return s;
  } catch {}
  const lc = (window.Telegram?.WebApp?.initDataUnsafe?.user?.language_code || navigator.language || '').toLowerCase();
  return lc.startsWith('ru') ? 'ru' : lc.startsWith('en') ? 'en' : 'uz';
}
export let LANG = detect();
export function setLang(l) {
  LANG = LANG_NAMES[l] ? l : 'uz';
  try { localStorage.setItem('sh_lang', LANG); } catch {}
  document.documentElement.lang = LANG === 'uzc' ? 'uz-Cyrl' : LANG;
}

