const RU = new Map(D.map((r) => [r[0], r[1]]));
const EN = new Map(D.map((r) => [r[0], r[2]]));

export function t(key, vars) {
  let s = LANG === 'ru' ? RU.get(key) ?? key : LANG === 'en' ? EN.get(key) ?? key : key;
  if (LANG === 'uzc') s = toCyrillic(s);
  if (!vars) return s;
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}

/** Boshqa tildagi matn (masalan, havola matni tanlangan tilda). */
export function tIn(lang, key, vars) {
  const o = LANG;
  LANG = LANG_NAMES[lang] ? lang : o;
  try { return [t(key, vars), nm(vars?.name)]; } finally { LANG = o; }
}

/** Ism va nomlarni joriy alifboda ko'rsatish (kirillda transliteratsiya). */
export const nm = (s) => (LANG === 'uzc' ? toCyrillic(s || '') : s || '');

const MONTHS = {
  uz: ['yanvar', 'fevral', 'mart', 'aprel', 'may', 'iyun', 'iyul', 'avgust', 'sentabr', 'oktabr', 'noyabr', 'dekabr'],
  ru: ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'],
  en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
};
const months = () => (LANG === 'ru' ? MONTHS.ru : LANG === 'en' ? MONTHS.en : MONTHS.uz.map((m) => (LANG === 'uzc' ? toCyrillic(m) : m)));

export function fmtDate(iso) {
  if (!iso) return '';
  const [y, m, d] = iso.split('-');
  const M = months();
  if (d) {
    if (LANG === 'en') return `${M[m - 1]} ${Number(d)}, ${y}`;
    if (LANG === 'ru') return `${Number(d)} ${M[m - 1]} ${y}`;
    return `${Number(d)}-${M[m - 1]}, ${y}`;
  }
  if (m) return `${LANG === 'ru' ? ['январь', 'февраль', 'март', 'апрель', 'май', 'июнь', 'июль', 'август', 'сентябрь', 'октябрь', 'ноябрь', 'декабрь'][m - 1] : M[m - 1]} ${y}`;
  return LANG === 'ru' ? `${y} г.` : LANG === 'en' ? y : t('{y}-yil', { y });
}
export const monthShort = (i) => months()[i].slice(0, 3);
export const fmtNum = (n) => Number(n).toLocaleString(LANG === 'en' ? 'en-US' : 'ru-RU');
